# PROTEKT map: the Proving Ground. Hand-authored; every feature below is a place you can drive to.
# A valley that limits movement, a ramp up, high ground that blocks weapons, an ambush pocket,
# and a drop you can fall down but not drive back up. Edit, then `protekt-map draw` to look.
# terrain: f flat, r rough, R ridge, c crater.  heights: integers, -512..512.
# solid: # impassable, . open.  Row 0 is the north edge; column 0 the west.

[map]
name = "Proving Ground"
seed = 0
width = 64
height = 64
